                ts("Skipped by difficulty / target bits", [(R("ha_relayer_relays_skipped_difficulty_total", "service_id"), "skipped {{service_id}}"),
                    (G("ha_query_relay_mining_difficulty_target_bits", "max", "service_id"), "target bits {{service_id}}")], "short",
                   "After the first settlement the difficulty rises and published falls below served by design.", w=8, h=9),
