                ts("Served outside the normal path", [(R("ha_relayer_relays_served_optimistically_total"), "optimistic"), (R("ha_relayer_relays_served_over_budget_total", "reason"), "over budget {{reason}}"),
                    (R("ha_relayer_undeclared_transport_served_total", "rpc_type"), "undeclared transport {{rpc_type}}"), (R("ha_relayer_live_connections_cut_total", "transport"), "live connection cut {{transport}}")], "reqps", w=12),
